window.KNOTS=[
{id:"clinch",n:"Verbesserter Clinchknoten",fuer:"Schnur an Wirbel, Haken, Köder",schnur:"Monofil, Fluorocarbon",lvl:"leicht",kraft:"ca. 90 %",url:"https://www.animatedknots.com/improved-clinch-knot",
 s:["Schnur 15 cm durch das Öhr führen.","Ende 5–7 Mal um die Hauptschnur wickeln.","Ende durch die kleine Schlaufe direkt über dem Öhr stecken.","Ende anschließend durch die neu entstandene große Schlaufe zurückführen.","Anfeuchten, an der Hauptschnur festziehen, Ende kürzen."]},
{id:"palomar",n:"Palomar-Knoten",fuer:"Schnur an Wirbel oder Haken, Dropshot",schnur:"Geflecht, Mono",lvl:"leicht",kraft:"ca. 95 %",url:"https://www.animatedknots.com/palomar-knot",
 s:["Schnur doppelt nehmen (15 cm Schlaufe) und die Schlaufe durch das Öhr stecken.","Mit der doppelten Schnur einen einfachen Überhandknoten binden, das Öhr hängt locker darin.","Den Wirbel oder Haken komplett durch die Schlaufe stecken.","Anfeuchten, an beiden Strängen gleichmäßig festziehen, Ende kürzen."],tipp:"Der sicherste Einsteigerknoten für Geflecht. Für Dropshot das Ende lang lassen und von oben noch einmal durchs Öhr führen."},
{id:"uni",n:"Uni-Knoten (Grinner)",fuer:"Schnur an Wirbel, Haken, Spule",schnur:"alle",lvl:"leicht",kraft:"ca. 90 %",url:"https://www.animatedknots.com/uni-knot",
 s:["Schnur 15 cm durch das Öhr, Ende parallel zur Hauptschnur zurücklegen.","Mit dem Ende eine Schlaufe bilden, die über beiden Strängen liegt.","Ende 5–6 Mal durch die Schlaufe um beide Stränge wickeln.","Am Ende zuziehen, dann den Knoten an der Hauptschnur zum Öhr schieben."]},
{id:"doppeluni",n:"Doppelter Uni",fuer:"Zwei Schnüre verbinden (Geflecht an Fluorocarbon)",schnur:"alle",lvl:"mittel",kraft:"ca. 85 %",url:"https://www.netknots.com/fishing_knots/double-uni-knot",
 s:["Beide Schnurenden 20 cm überlappend nebeneinanderlegen.","Mit dem Geflecht einen Uni-Knoten um das Fluorocarbon binden, 8–10 Windungen (Geflecht rutscht sonst).","Mit dem Fluorocarbon einen Uni-Knoten um das Geflecht binden, 4–5 Windungen.","Beide Knoten einzeln vorziehen, dann an den Hauptschnüren zusammenschieben und fest anziehen."]},
{id:"fg",n:"FG-Knoten",fuer:"Geflecht an Fluorocarbon oder Mono, sehr schlank",schnur:"Geflecht + Mono",lvl:"schwer",kraft:"ca. 95 %",url:"https://www.animatedknots.com/fg-knot",
 s:["Geflecht straff spannen (zum Beispiel zwischen Rolle und Zähnen).","Fluorocarbon im Kreuzschlag einbinden: das Geflecht abwechselnd von oben und von unten um das Fluorocarbon schlagen, 16–20 Mal.","Wicklung mit 2 halben Schlägen sichern und fest anziehen.","Fluorocarbon-Ende kurz abschneiden, mit dem Geflecht 4–6 weitere halbe Schläge um die Hauptschnur, dann 2 Schläge rückwärts. Kürzen."],tipp:"Gleitet am besten durch die Ringe. Zum Einstieg erst den Doppelten Uni lernen."},
{id:"albright",n:"Albright-Knoten",fuer:"Dünne an sehr dicke Schnur (Hardmono, Schlagschnur)",schnur:"Geflecht + Hardmono",lvl:"mittel",kraft:"ca. 85 %",url:"https://www.animatedknots.com/albright-knot",
 s:["Mit der dicken Schnur eine Schlaufe legen (U-Form).","Dünne Schnur 15 cm durch die Schlaufe führen.","Dünne Schnur 10–12 Mal eng um alle drei Stränge wickeln, Richtung Schlaufenende.","Ende wieder durch die Schlaufe herausführen, auf derselben Seite, auf der es hineinkam.","Anfeuchten, alle vier Enden gleichmäßig anziehen, kürzen."]},
{id:"chirurg",n:"Chirurgenschlaufe",fuer:"Schlaufe am Schnurende",schnur:"alle",lvl:"leicht",kraft:"ca. 85 %",url:"https://www.animatedknots.com/surgeons-loop-knot",
 s:["Schnurende doppelt legen (Schlaufe).","Mit der Doppelschnur einen Überhandknoten binden.","Die Schlaufe ein zweites Mal durch den Knoten führen.","Anfeuchten und festziehen."]},
{id:"schlaufe2",n:"Schlaufe in Schlaufe",fuer:"Vorfach an Hauptschnur ohne Wirbel",schnur:"alle",lvl:"leicht",kraft:"–",
 s:["Die Schlaufe der Hauptschnur durch die Vorfachschlaufe stecken.","Das Vorfachende mit dem Haken durch die Schlaufe der Hauptschnur führen.","Zuziehen. Die Schlaufen müssen flach ineinanderliegen wie ein Kreuzknoten."],tipp:"Liegt eine Schlaufe als Schlinge um die andere, schneidet sie ein. Dann neu legen."},
{id:"rapala",n:"Schlaufenknoten (Rapala-Knoten)",fuer:"Kunstköder und Fliegen, die frei spielen sollen",schnur:"Monofil, Fluorocarbon",lvl:"mittel",kraft:"ca. 85 %",
 s:["12 cm vor dem Ende einen lockeren Überhandknoten in die Schnur legen.","Ende durch das Köderöhr und zurück durch den Überhandknoten führen.","Ende 3 Mal um die Hauptschnur wickeln.","Ende zurück durch den Überhandknoten führen und dann durch die dabei entstandene Schlaufe.","Anfeuchten und festziehen. Vor dem Öhr bleibt eine kleine offene Schlaufe."]},
{id:"dropper",n:"Seitenarm-Schlaufe (Dropper Loop)",fuer:"Seitenarm für Beifänger, Paternoster",schnur:"Monofil, Fluorocarbon",lvl:"mittel",kraft:"ca. 80 %",
 s:["Einen Kreis in die Schnur legen.","Eine Seite des Kreises 5–6 Mal um die Kreuzungsstelle wickeln.","In der Mitte der Wicklungen eine Öffnung halten und den gegenüberliegenden Kreisbogen hindurchstecken.","Diesen Bogen festhalten, anfeuchten und an beiden Schnurenden ziehen.","Die Schlaufe steht jetzt seitlich ab. Haken einschlaufen oder einen Schenkel der Schlaufe durchschneiden: fertig ist der Seitenarm."]},
{id:"blut",n:"Blutknoten",fuer:"Zwei ähnlich dicke Monoschnüre verbinden (Vorfachspitze)",schnur:"Monofil, Fluorocarbon",lvl:"mittel",kraft:"ca. 85 %",
 s:["Beide Schnüre 15 cm überlappen.","Ein Ende 5 Mal um die andere Schnur wickeln und zurück in die Mitte zwischen beide Schnüre stecken.","Das andere Ende 5 Mal in Gegenrichtung wickeln und von der anderen Seite durch dieselbe Öffnung stecken.","Anfeuchten, an beiden Hauptschnüren ziehen, Enden kürzen."]},
{id:"noknot",n:"No-Knot (knotenloser Knoten)",fuer:"Öhrhaken mit Haar für Boilie und Pellet",schnur:"Vorfachgeflecht, Mono",lvl:"leicht",kraft:"ca. 95 %",
 s:["Kleine Schlaufe für den Köder ans Vorfachende binden.","Vorfach von hinten durch das Öhr führen (von der Rückseite zur Hakenspitze hin) und die Haarlänge einstellen.","Das Haar am Schenkel anlegen. Mit der langen Schnur 7–8 Mal eng um Schenkel und Haar wickeln, Richtung Hakenbogen.","Die Schnur wieder von hinten durch das Öhr führen.","Festziehen."]},
{id:"plaettchen",n:"Plättchenhaken binden",fuer:"Haken ohne Öhr (Friedfisch, Forelle, Aal)",schnur:"Monofil, Fluorocarbon",lvl:"mittel",kraft:"ca. 90 %",
 s:["Schnur am Hakenschenkel entlanglegen und eine Schlaufe bilden, das Ende zeigt zum Plättchen.","Mit dem Ende 6–8 Mal durch die Schlaufe um Schenkel und Schnur wickeln (wie beim Uni-Knoten).","Anfeuchten, an beiden Enden zuziehen und den Knoten bis ans Plättchen schieben.","Die Schnur muss auf der Innenseite des Plättchens abgehen, also zur Hakenspitze hin."],tipp:"Fertig gebundene Vorfachhaken sparen am Wasser viel Zeit."},
{id:"stopper",n:"Stopperknoten",fuer:"Stopper für die Laufpose",schnur:"Stopperfaden auf der Hauptschnur",lvl:"leicht",kraft:"–",url:"https://www.netknots.com/fishing_knots/bobber-stopper-knot",
 s:["Ein 20 cm langes Stück Stopperfaden parallel an die Hauptschnur legen und eine Schlaufe bilden.","Ende 4–5 Mal durch die Schlaufe um die Hauptschnur wickeln.","Beide Enden zuziehen und auf 1 cm kürzen (so gleiten sie durch die Ringe).","Der Knoten lässt sich verschieben: So stellst du die Angeltiefe ein."]},
{id:"arbor",n:"Arbor-Knoten",fuer:"Schnur auf die Rollenspule",schnur:"alle",lvl:"leicht",kraft:"–",url:"https://www.animatedknots.com/arbor-knot",
 s:["Schnur um die Spule legen.","Mit dem Ende einen Überhandknoten um die Hauptschnur binden.","Ins Ende einen zweiten Überhandknoten als Stopper binden.","Zuziehen und an die Spule schieben."],tipp:"Bei Geflecht vorher etwas Mono unterfüttern oder ein Stück Klebeband auf die Spule, sonst rutscht die Schnur durch."},
{id:"crimp",n:"Quetschhülse (Stahlvorfach)",fuer:"Stahl, Titan und dickes Mono an Wirbel, Haken, Snap",schnur:"Stahl 7×7, 1×7, Titan, Hardmono",lvl:"leicht",kraft:"ca. 90 %",
 s:["Hülse aufs Vorfach schieben. Das Ende durch Wirbel oder Haken und zurück durch die Hülse führen, eine kleine Schlaufe lassen.","Bei weichem 7×7-Stahl das Ende ein zweites Mal durch die Hülse führen.","Mit der Quetschhülsenzange zweimal quetschen, die Ränder der Hülse dabei frei lassen.","Kräftig auf Zug prüfen."],tipp:"Die Hülse muss zum Durchmesser passen. Mit einer Kombizange gequetschte Hülsen schneiden das Vorfach an."}
];
